public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        minLen = Math.min(minLen, s.length());
    }
    for (int len = minLen; len >= 1; len--) {
        Set<String> candidates = new HashSet<>();
        String first = strings.get(0);
        for (int i = 0; i <= first.length() - len; i++) {
            String sub = first.substring(i, i + len);
            candidates.add(sub);
            candidates.add(new StringBuilder(sub).reverse().toString());
        }
        if (candidates.isEmpty()) {
            continue;
        }
        for (int idx = 1; idx < strings.size() && !candidates.isEmpty(); idx++) {
            String str = strings.get(idx);
            Set<String> current = new HashSet<>();
            for (int i = 0; i <= str.length() - len; i++) {
                String sub = str.substring(i, i + len);
                current.add(sub);
                current.add(new StringBuilder(sub).reverse().toString());
            }
            candidates.retainAll(current);
        }
        if (!candidates.isEmpty()) {
            return len;
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String first = strings.get(0);
    int n = first.length();

    // Helper to check if a candidate substring satisfies all strings
    java.util.function.Predicate<String> satisfiesAll = candidate -> {
        for (int idx = 1; idx < strings.size(); idx++) {
            String s = strings.get(idx);
            String rev = new StringBuilder(candidate).reverse().toString();
            if (!(s.contains(candidate) || s.contains(rev))) {
                return false;
            }
        }
        return true;
    };

    // Try lengths from longest to shortest
    for (int len = n; len > 0; len--) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        for (int i = 0; i <= n - len; i++) {
            String sub = first.substring(i, i + len);
            if (seen.contains(sub)) continue;
            seen.add(sub);
            // Check for first string itself
            if (!(first.contains(sub) || first.contains(new StringBuilder(sub).reverse().toString()))) {
                // If it isn't in the first string either forward or reverse, cannot be candidate
                continue;
            }
            if (satisfiesAll.test(sub)) {
                return len;
            }
        }
    }
    return 0;
}

