public static int countOilDeposits(char[][] grid) {
    int rows = grid.length;
    if (rows == 0) return 0;
    int cols = grid[0].length;
    if (cols == 0) return 0;

    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;

    // 8-directional moves
    int[] dRow = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dCol = {-1, 0, 1, -1, 1, -1, 0, 1};

    java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                deposits++;
                // start DFS
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0], cc = pos[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dRow[k];
                        int nc = cc + dCol[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                            if (grid[nr][nc] == '@' && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                stack.push(new int[]{nr, nc});
                            }
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

public static int maxRegions(int N) {
    if (N <= 0) {
        return 1; // no triangles => only one region (the whole plane)
    }
    // Maximum number of regions formed by N triangles in general position
    // Formula: 3 * N^2 - 3 * N + 2
    return 3 * N * N - 3 * N + 2;
}

