public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length < 2 || end.length < 2) {
        return "cannot be travelled";
    }
    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] p : paths) {
            if (p == null || p.length < 4) continue;
            String a = p[0] + "," + p[1];
            String b = p[2] + "," + p[3];
            adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
            adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
        }
    }
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = adj.get(current);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                if (nb.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Determine if start and end are single indices or coordinate pairs
    boolean isCoord = start.length > 1 && end.length > 1;
    int startId, endId, maxNodeId = -1;

    if (isCoord) {
        startId = start[0] * n + start[1];
        endId = end[0] * n + end[1];
        maxNodeId = n * n - 1;
    } else {
        startId = start[0];
        endId = end[0];
        for (int[] p : paths) {
            if (p.length > 0) maxNodeId = Math.max(maxNodeId, p[0]);
            if (p.length > 1) maxNodeId = Math.max(maxNodeId, p[1]);
        }
        maxNodeId = Math.max(maxNodeId, Math.max(startId, endId));
    }

    // Quick check if start equals end
    if (startId == endId) return "can be travelled";

    // Build adjacency list
    @SuppressWarnings("unchecked")
    List<Integer>[] adj = new ArrayList[maxNodeId + 1];
    for (int i = 0; i <= maxNodeId; i++) adj[i] = new ArrayList<>();
    for (int[] e : paths) {
        if (e.length < 2) continue;
        int u, v;
        if (isCoord && e.length >= 4) {
            u = e[0] * n + e[1];
            v = e[2] * n + e[3];
        } else if (e.length == 2) {
            u = e[0];
            v = e[1];
        } else {
            // Unsupported format; skip
            continue;
        }
        if (u <= maxNodeId && v <= maxNodeId) {
            adj[u].add(v);
            adj[v].add(u);
        }
    }

    // BFS to find reachability
    boolean[] visited = new boolean[maxNodeId + 1];
    Deque<Integer> queue = new ArrayDeque<>();
    visited[startId] = true;
    queue.add(startId);

    while (!queue.isEmpty()) {
        int cur = queue.poll();
        if (cur == endId) return "can be travelled";
        for (int nb : adj[cur]) {
            if (!visited[nb]) {
                visited[nb] = true;
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Convert coordinates to string keys for hashing
    java.util.function.Function<int[], String> coordKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    String startKey = coordKey.apply(start);
    String endKey = coordKey.apply(end);

    // Edge case: start equals end
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();

    for (int[] path : paths) {
        if (path == null || path.length != 2 * n) {
            // Skip malformed path definitions
            continue;
        }
        int[] a = new int[n];
        int[] b = new int[n];
        System.arraycopy(path, 0, a, 0, n);
        System.arraycopy(path, n, b, 0, n);
        String aKey = coordKey.apply(a);
        String bKey = coordKey.apply(b);

        adj.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
        adj.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey);
    }

    // BFS to check connectivity
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String curr = queue.poll();
        java.util.List<String> neigh = adj.getOrDefault(curr, java.util.Collections.emptyList());
        for (String nb : neigh) {
            if (!visited.contains(nb)) {
                if (nb.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(nb);
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    int src = start[0];
    int dst = end[0];
    if (src == dst) {
        return "can be travelled";
    }
    // Build adjacency list
    java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>();
    for (int i = 0; i < n; i++) {
        adj.add(new java.util.ArrayList<>());
    }
    for (int[] p : paths) {
        if (p.length >= 2) {
            int u = p[0];
            int v = p[1];
            if (u >= 0 && u < n && v >= 0 && v < n) {
                adj.get(u).add(v);
                adj.get(v).add(u);
            }
        }
    }
    // BFS to find path
    boolean[] visited = new boolean[n];
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    visited[src] = true;
    queue.add(src);
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        for (int nb : adj.get(cur)) {
            if (!visited[nb]) {
                if (nb == dst) {
                    return "can be travelled";
                }
                visited[nb] = true;
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

