public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    if (k <= 0) {
        return false; // division by non-positive k is undefined here
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }
    if (freq[0] % 2 != 0) {
        return false;
    }
    for (int i = 1; i < k; i++) {
        int j = k - i;
        if (i > j) {
            continue; // already handled as counterpart
        }
        if (i == j) { // occurs when k is even and i == k/2
            if (freq[i] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[i] != freq[j]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) return false;
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        freq[rem]++;
    }
    // Remainder 0 must have even count
    if (freq[0] % 2 != 0) return false;
    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) continue; // already handled for even k
        if (freq[r] != freq[k - r]) return false;
    }
    return true;
}

