    for (int i = 0; i < n; i++) graph[i] = new java.util.ArrayList<>();
    for (int i = 0; i < edges.length; i++) {
        int u = edges[i][0];
        int v = edges[i][1];
        graph[u].add(v);
        graph[v].add(u);
    }
    return dfs(0, -1, graph, hasApple);
}

private int dfs(int node, int parent, java.util.ArrayList<Integer>[] graph, boolean[] hasApple) {
    int total = 0;
    for (int neighbor : graph[node]) {
        if (neighbor == parent) continue;
        int childCost = dfs(neighbor, node, graph, hasApple);
        if (childCost > 0 || hasApple[neighbor]) {
            total += childCost + 2;
        }
    }
    return total;
}

public String sortString(String s) {
    // Frequency array for lowercase letters 'a' to 'z'
    int[] freq = new int[26];
    for (int i = 0; i < s.length(); i++) {
        freq[s.charAt(i) - 'a']++;
    }
    StringBuilder result = new StringBuilder();
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass: pick smallest to largest
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
        // Descending pass: pick largest to smallest
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
    }
    return result.toString();
}

