    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder result = new StringBuilder();
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
        // Descending pass
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (freq[i] > 0) {
                result.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    int total = 0;
    for (int num : nums) {
        total += num;
    }
    java.util.ArrayList<java.util.Set<Integer>> dp = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        dp.add(new java.util.HashSet<>());
    }
    dp.get(0).add(0);
    for (int num : nums) {
        for (int k = Math.min(n - 1, n); k >= 1; k--) {
            if (dp.get(k - 1).isEmpty()) {
                continue;
            }
            for (int prevSum : dp.get(k - 1)) {
                dp.get(k).add(prevSum + num);
            }
        }
    }
    for (int k = 1; k < n; k++) {
        if ((total * k) % n != 0) {
            continue;
        }
        int target = (total * k) / n;
        if (dp.get(k).contains(target)) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int total = 0;
    for (int num : nums) total += num;
    if (n <= 1) return false;
    long totalLong = total;
    int limit = 1 << n;
    for (int mask = 1; mask < limit; mask++) {
        int bits = Integer.bitCount(mask);
        if (bits == n) continue; // skip full array
        long sum = 0;
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) != 0) sum += nums[i];
        }
        if (sum * n == totalLong * bits) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int total = 0;
    for (int num : nums) total += num;
    java.util.List<java.util.HashSet<Integer>> sums = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) sums.add(new java.util.HashSet<>());
    sums.get(0).add(0);
    for (int num : nums) {
        for (int k = n - 1; k >= 0; k--) {
            if (sums.get(k).isEmpty()) continue;
            for (int s : sums.get(k)) {
                sums.get(k + 1).add(s + num);
            }
        }
    }
    for (int k = 1; k < n; k++) {
        if ((total * k) % n != 0) continue;
        int target = (total * k) / n;
        if (sums.get(k).contains(target)) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // Use meet-in-the-middle
    int mid = n / 2;
    int leftSize = mid;
    int rightSize = n - mid;
    // Map from subset size to set of possible sums in right half
    @SuppressWarnings("unchecked")
    java.util.HashSet<Long>[] rightSumsBySize = new java.util.HashSet[rightSize + 1];
    for (int i = 0; i <= rightSize; i++) {
        rightSumsBySize[i] = new java.util.HashSet<>();
    }
    // Enumerate all subsets of right half
    int rightMaskCount = 1 << rightSize;
    for (int mask = 0; mask < rightMaskCount; mask++) {
        int count = Integer.bitCount(mask);
        long sum = 0;
        for (int i = 0; i < rightSize; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[mid + i];
            }
        }
        rightSumsBySize[count].add(sum);
    }
    // Check each possible total subset size k (1..n-1)
    for (int k = 1; k <= n - 1; k++) {
        // sum of subset of size k must be integer
        if ((totalSum * k) % n != 0) continue;
        long targetSum = (totalSum * k) / n;
        // Enumerate subsets of left half
        int leftMaskCount = 1 << leftSize;
        for (int mask = 0; mask < leftMaskCount; mask++) {
            int countLeft = Integer.bitCount(mask);
            int countRight = k - countLeft;
            if (countRight < 0 || countRight > rightSize) continue;
            long sumLeft = 0;
            for (int i = 0; i < leftSize; i++) {
                if ((mask & (1 << i)) != 0) {
                    sumLeft += nums[i];
                }
            }
            long requiredRight = targetSum - sumLeft;
            if (rightSumsBySize[countRight].contains(requiredRight)) {
                return true;
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    int prev2 = 0; // cost to reach step 0
    int prev1 = 0; // cost to reach step 1
    for (int i = 2; i <= n; i++) {
        int curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int cur = Math.min(prev1, prev2) + cost[i];
        prev2 = prev1;
        prev1 = cur;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int stepOne = dp[i - 1] + cost[i - 1];
        int stepTwo = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(stepOne, stepTwo);
    }
    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    int prev2 = 0; // cost to reach step 0
    int prev1 = 0; // cost to reach step 1
    for (int i = 2; i <= n; i++) {
        int cur = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int dpPrevPrev = 0; // cost to reach step 0
    int dpPrev = 0;     // cost to reach step 1
    for (int i = 2; i <= n; i++) {
        int dpCurrent = cost[i - 1] + Math.min(dpPrevPrev, dpPrev);
        dpPrevPrev = dpPrev;
        dpPrev = dpCurrent;
    }
    return Math.min(dpPrevPrev, dpPrev);
}

