    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int val = 0;
    int count = 0;
    for (int i = 0; i < n; i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[val]) {
                seen[val] = true;
                count++;
                if (count == total) return true;
            }
        }
    }
    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    if (k == 0) {
        return true;
    }
    int total = 1 << k;
    if (s.length() < k) {
        return false;
    }
    boolean[] seen = new boolean[total];
    int mask = 0;
    int maxMask = total - 1;
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        mask = ((mask << 1) | (s.charAt(i) - '0')) & maxMask;
        if (i >= k - 1) {
            if (!seen[mask]) {
                seen[mask] = true;
                count++;
                if (count == total) {
                    return true;
                }
            }
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) return false;
    int total = 1 << k;                     // all binary strings of length k
    if (total == 0) return false;           // in case k >= 31, shift overflow
    boolean[] seen = new boolean[total];
    int count = 0;
    int mask = total - 1;                    // keeps only k bits
    int value = 0;
    // build first value of length k
    for (int i = 0; i < k; i++) {
        value = (value << 1) | (s.charAt(i) - '0');
    }
    if (!seen[value]) {
        seen[value] = true;
        count++;
    }
    // slide window
    for (int i = k; i < s.length(); i++) {
        value = ((value << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[value]) {
            seen[value] = true;
            count++;
            if (count == total) return true;   // early exit
        }
    }
    return count == total;
}

