public int minInsertions(String s) {
    int insertions = 0;
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                insertions++;   // need to insert a '(' before this ')'
            } else {
                balance--;       // match this ')' with an existing '('
            }
        }
    }
    // remaining unmatched '(' need a ')' each
    return insertions + balance;
}

public int minInsertions(String s) {
    int ans = 0;
    int bal = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            bal++;
        } else {
            bal--;
            if (bal < 0) {
                ans++;   // insert a '(' before this ')'
                bal = 0;
            }
        }
    }
    ans += bal; // need bal ')' at the end
    return ans;
}

public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int insertions = 0;
    int balance = 0; // number of unmatched '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                insertions++; // need an extra '(' before this ')'
                balance++;    // treat it as matched
            }
            balance--; // consume the ')'
        }
    }
    // Any remaining unmatched '(' need ')'
    insertions += balance;
    return insertions;
}

public int minInsertions(String s) {
    int insertions = 0;
    int open = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++;
        } else if (c == ')') {
            if (open > 0) {
                open--;
            } else {
                // Need to insert a '(' before this ')'
                insertions++;
                // The inserted '(' pairs with this ')', so open stays 0
            }
        }
    }
    // All remaining '(' need closing ')'
    return insertions + open;
}

public int minInsertions(String s) {
    int needInsertions = 0;
    int openCount = 0; // number of unmatched '('

    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch == '(') {
            openCount++;
        } else if (ch == ')') {
            if (openCount > 0) {
                openCount--; // match with a previous '('
            } else {
                needInsertions++; // insert a '(' before this ')'
            }
        }
    }
    // any remaining unmatched '(' require a ')' after them
    return needInsertions + openCount;
}

public int minOperations(int n) {
    if (n <= 1) {
        return 0;
    }
    if (n % 2 == 0) {
        int m = n / 2;
        return m * m;
    } else {
        int m = (n - 1) / 2;
        return m * (m + 1);
    }
}

public int minOperations(int n) {
    long sum = 0;
    int target = n;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        if (val > target) {
            sum += val - target;
        }
    }
    return (int) sum;
}

