        maxSum = Math.max(maxSum, curMax);
        curMin = Math.min(num, curMin + num);
        minSum = Math.min(minSum, curMin);
    }
    return Math.max(maxSum, -minSum);
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50];
    int fibSize = 0;
    fib[fibSize++] = 1;
    fib[fibSize++] = 1;
    while (true) {
        long next = (long) fib[fibSize - 1] + fib[fibSize - 2];
        if (next > k) break;
        fib[fibSize++] = (int) next;
    }

    // Greedy selection: always pick the largest Fibonacci number <= remaining value
    int count = 0;
    int remaining = k;
    while (remaining > 0) {
        for (int i = fibSize - 1; i >= 0; i--) {
            if (fib[i] <= remaining) {
                remaining -= fib[i];
                count++;
                break;
            }
        }
    }
    return count;
}

