}

private void dfs(int start, Set<String> seen, int count, String s, int[] max) {
    if (start == s.length()) {
        if (count > max[0]) {
            max[0] = count;
        }
        return;
    }
    // Prune if remaining characters cannot exceed current max
    if (count + (s.length() - start) <= max[0]) {
        return;
    }
    for (int end = start + 1; end <= s.length(); end++) {
        String sub = s.substring(start, end);
        if (seen.contains(sub)) {
            continue;
        }
        seen.add(sub);
        dfs(end, seen, count + 1, s, max);
        seen.remove(sub);
    }
}

