    int extra = k - n;
    char[] arr = new char[n];
    for (int i = 0; i < n; i++) {
        arr[i] = 'a';
    }
    for (int i = n - 1; i >= 0 && extra > 0; i--) {
        int inc = Math.min(25, extra);
        arr[i] = (char)('a' + inc);
        extra -= inc;
    }
    return new String(arr);
}

