public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    Arrays.sort(A);
    boolean[] used = new boolean[n];
    int[] countHolder = new int[1];
    dfs(0, -1, A, used, countHolder);
    return countHolder[0];
}

private static void dfs(int depth, int prevIndex, int[] A, boolean[] used, int[] countHolder) {
    if (depth == A.length) {
        countHolder[0]++;
        return;
    }
    for (int i = 0; i < A.length; i++) {
        if (used[i]) continue;
        if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;
        if (depth > 0) {
            int sum = A[i] + A[prevIndex];
            int root = (int) Math.sqrt(sum);
            if (root * root != sum) continue;
        }
        used[i] = true;
        dfs(depth + 1, i, A, used, countHolder);
        used[i] = false;
    }
}

