public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int s = 0; s <= m + n - 2; s++) {
        if (s % 2 == 0) {
            int iStart = Math.min(s, m - 1);
            int iEnd = Math.max(0, s - (n - 1));
            for (int i = iStart; i >= iEnd; i--) {
                int j = s - i;
                result[idx++] = mat[i][j];
            }
        } else {
            int iStart = Math.max(0, s - (n - 1));
            int iEnd = Math.min(s, m - 1);
            for (int i = iStart; i <= iEnd; i++) {
                int j = s - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

