    int index = 0;
    for (int sum = 0; sum < m + n - 1; sum++) {
        int rowStart = Math.max(0, sum - (n - 1));
        int rowEnd = Math.min(m - 1, sum);
        if (sum % 2 == 0) { // even sum: traverse from bottom to top
            for (int i = rowEnd; i >= rowStart; i--) {
                int j = sum - i;
                result[index++] = mat[i][j];
            }
        } else { // odd sum: traverse from top to bottom
            for (int i = rowStart; i <= rowEnd; i++) {
                int j = sum - i;
                result[index++] = mat[i][j];
            }
        }
    }
    return result;
}

