    int[] result = new int[rows * cols];
    int idx = 0;
    int diagonalCount = rows + cols - 1;
    for (int d = 0; d < diagonalCount; d++) {
        if (d % 2 == 0) {
            // even diagonal - traverse from bottom to top
            int r = Math.min(d, rows - 1);
            int c = d - r;
            while (r >= 0 && c < cols) {
                result[idx++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            // odd diagonal - traverse from top to bottom
            int c = Math.min(d, cols - 1);
            int r = d - c;
            while (c >= 0 && r < rows) {
                result[idx++] = mat[r][c];
                r++;
                c--;
            }
        }
    }
    return result;
}

