        int end = Math.min(k, m - 1);
        if (k % 2 == 0) {
            for (int i = end; i >= start; i--) {
                res[idx++] = mat[i][k - i];
            }
        } else {
            for (int i = start; i <= end; i++) {
                res[idx++] = mat[i][k - i];
            }
        }
    }
    return res;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // no larger permutation
    }
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse the suffix starting at i+1
    int left = i + 1, right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    // convert back to integer, checking overflow
    long result = 0;
    for (char c : digits) {
        result = result * 10 + (c - '0');
        if (result > Integer.MAX_VALUE) {
            return -1; // overflow, cannot fit in int
        }
    }
    return (int) result;
}

