public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[] current = new char[n];
    backtrack(0, n - 1, current, result);
    return result;
}

private static void backtrack(int left, int right, char[] current, List<String> result) {
    if (left > right) {
        result.add(new String(current));
        return;
    }
    if (left == right) {
        current[left] = '0';
        result.add(new String(current));
        current[left] = '1';
        result.add(new String(current));
        current[left] = '8';
        result.add(new String(current));
        return;
    }
    char[][] pairs = { {'0','0'}, {'1','1'}, {'6','9'}, {'8','8'}, {'9','6'} };
    for (char[] pair : pairs) {
        if (left == 0 && pair[0] == '0') {
            continue; // skip leading zero
        }
        current[left] = pair[0];
        current[right] = pair[1];
        backtrack(left + 1, right - 1, current, result);
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int x0 = points[0][0], y0 = points[0][1];
    int x1 = points[1][0], y1 = points[1][1];
    int x2 = points[2][0], y2 = points[2][1];

    // Check for duplicate points
    if ((x0 == x1 && y0 == y1) || (x0 == x2 && y0 == y2) || (x1 == x2 && y1 == y2)) {
        return false;
    }

    // Compute twice the area of the triangle formed by the points
    long area2 = (long)(x1 - x0) * (y2 - y0) - (long)(x2 - x0) * (y1 - y0);
    return area2 != 0;
}

